SourceCode.Declaration:
/// <summary>
/// PricingAttribute of table <c>CustTable</c> field DlvTerm.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, DlvTerm))]
internal class GUPPricingAttributeCustTableDlvTerm extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, DlvTerm);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable custTable;
    DlvTerm   dlvTerm;

    while select DlvTerm from custtable
        group by DlvTerm
        join dlvTerm
        group by Code, Txt
        where custTable.DlvTerm == dlvTerm.Code
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(dlvTerm.Code, dlvTerm.Txt);
        ret.add(valueObject);
    }
    return ret;
}
